function draw2D(){const W=canvas.width,H=canvas.height;ctx.globalCompositeOperation='source-over';ctx.fillStyle='#080b12';ctx.fillRect(0,0,W,H);const bg=ctx.createRadialGradient(W*.5,H*.43,0,W*.5,H*.43,H*.65);bg.addColorStop(0,work.engine==='tree'?'#2035294d':work.engine==='tetra'?'#57352435':'#12364c44');bg.addColorStop(1,'#080b1200');ctx.fillStyle=bg;ctx.fillRect(0,0,W,H);
 if(work.engine==='tree'){ctx.globalCompositeOperation='screen';const wind=pointer[0]*.23,windZ=pointer[1]*.16;for(const g of geometry){if(g.depth>growth)continue;const bend=p=>[p[0]+Math.pow(Math.max(0,1.3-p[1]),1.7)*wind,p[1],p[2]+Math.pow(Math.max(0,1.3-p[1]),1.5)*windZ+Math.sin(clock*.6+p[1]*3)*.012*(g.depth+1)];let a=projection(bend(g.a)),b=projection(bend(g.b)),fraction=Math.min(1,growth-g.depth);b=lerp(a,b,fraction);const width=Math.max(.4,(paramA-g.depth+1)*.32*H/700);stroke([a,b],hue(95+g.depth*7,.55),width);if(g.depth===Math.round(paramA)&&fraction>.5){ctx.fillStyle=hue(75+g.id%35,.65);ctx.beginPath();ctx.arc(b[0],b[1],1.2*H/700,0,Math.PI*2);ctx.fill()}}ctx.globalCompositeOperation='source-over'}
 if(work.engine==='tetra'){let faces=geometry.map(g=>{const p=g.points.map(projection);return{p,z:p.reduce((a,b)=>a+b[2],0)/3,depth:g.depth}}).sort((a,b)=>b.z-a.z);for(const face of faces){const p=face.p,light=Math.max(.15,.6-face.z*.17);ctx.beginPath();ctx.moveTo(p[0][0],p[0][1]);ctx.lineTo(p[1][0],p[1][1]);ctx.lineTo(p[2][0],p[2][1]);ctx.closePath();ctx.fillStyle=`hsla(${25+palette*72+face.depth*5},${45+face.depth*5}%,${light*50}%,.88)`;ctx.fill();ctx.strokeStyle=hue(22+face.depth*8,.55);ctx.lineWidth=.45;ctx.stroke()}}
 if(work.engine==='chaos'){ctx.globalCompositeOperation='screen';const count=Math.min(Math.floor(cloudProgress),Math.floor(72000*paramB));for(let i=0;i<count;i+=2){const p=projection(cloud[i]);ctx.fillStyle=hue(165+cloud[i][2]*60,.21);ctx.fillRect(p[0],p[1],1,1)}ctx.globalCompositeOperation='source-over'}
}
function draw(){if(['bulb','menger','julia'].includes(work.engine))drawGL();else draw2D();dirty=false}
if(['bulb','menger','julia'].includes(work.engine))initGL();else{ctx=canvas.getContext('2d',{alpha:false});if(!ctx)fail('Your browser could not create a Canvas drawing context.')}rebuild();resize();
function frame(now){requestAnimationFrame(frame);const dt=Math.min(.045,(now-last)/1000);last=now;if(!visible||$('#error').hidden===false)return;let moving=false;if(!$('#help-dialog').open){const dx=(held.has('ArrowRight')?1:0)-(held.has('ArrowLeft')?1:0),dy=(held.has('ArrowDown')?1:0)-(held.has('ArrowUp')?1:0);if(dx||dy){moving=true;if(work.engine==='julia'){pan[0]+=dx*dt*distance;pan[1]-=dy*dt*distance}else{yaw+=dx*dt*.8;pitch=Math.max(-1.4,Math.min(1.4,pitch+dy*dt*.7))}}}if(!paused){clock+=dt;if(!drag&&auto&&work.engine!=='julia'){yaw+=dt*.065;moving=true}if(work.engine==='tree'){growth=Math.min(paramA+1,growth+dt*1.2);moving=true}if(work.engine==='chaos'){cloudProgress=Math.min(cloud.length,cloudProgress+dt*16000);moving=true}if(work.engine==='julia'&&!locked){moving=true}}if((dirty||moving)&&now-lastDraw>1000/30){draw();lastDraw=now}}
if(reduced){growth=paramA+1;cloudProgress=cloud.length}draw();requestAnimationFrame(frame);
